export default {
  async fetch(request, env) {
    const url = new URL(request.url);

    // تست D1
    if (url.pathname === "/test-db") {
      const result = await env.DB
        .prepare("SELECT COUNT(*) AS count FROM buttons")
        .first();

      return new Response(
        JSON.stringify({
          ok: true,
          buttons: result.count
        }),
        {
          headers: {
            "content-type": "application/json; charset=UTF-8"
          }
        }
      );
    }

    // Telegram Webhook
    if (url.pathname.startsWith("/webhook/") && request.method === "POST") {
      const secret = request.headers.get(
        "X-Telegram-Bot-Api-Secret-Token"
      );

      if (secret !== env.WEBHOOK_SECRET) {
        return new Response("Unauthorized", { status: 401 });
      }

      const update = await request.json();

      const chatId =
        update.message?.chat?.id ||
        update.callback_query?.message?.chat?.id;

      const user = await env.DB
        .prepare("SELECT account_type FROM users WHERE CAST(telegram_id AS INTEGER) = ?")
        .bind(String(chatId))
        .first();

      console.log("User account:", user);

      const userId =
        update.message?.from?.id ||
        update.callback_query?.from?.id;

      // =========================
      // /start
      // =========================
      if (update.message?.text === "/start" && chatId) {

        const welcomeText =
`🌟 به ربات اختصاصی دانشجویان اتاق عمل کد 1️⃣ خوش آمدید.

از طریق این ربات می‌توانید:

📚 به جزوه‌ها و فایل‌های آموزشی دسترسی داشته باشید.
🎓 از محتوای اختصاصی بهره‌مند شوید.
💯 و از امکانات متنوع ربات برای یادگیری بهتر استفاده کنید.

لطفاً یکی از گزینه‌های زیر را انتخاب کنید.`;

        // مدیر ربات
        if (String(userId) === String(env.ADMIN_ID)) {

          await fetch(
            `https://api.telegram.org/bot${env.BOT_TOKEN}/sendMessage`,
            {
              method: "POST",
              headers: {
                "content-type": "application/json"
              },
              body: JSON.stringify({
                chat_id: chatId,
                text: welcomeText,
                reply_markup: {
                  inline_keyboard: [
                    [
                      {
                        text: "🛠 پنل مدیریت",
                        callback_data: "admin_panel"
                      },
                      {
                        text: "👤 نمای کاربر",
                        callback_data: "user_view"
                      }
                    ]
                  ]
                }
              })
            }
          );

          return new Response("OK");
        }

        // =========================
        // کاربر عادی
        // =========================

        const result = await env.DB
          .prepare(`
            SELECT id, title
            FROM buttons
            WHERE parent_id = 0
              AND visible = 1
              AND deleted = 0
            ORDER BY position ASC
          `)
          .all();

        const keyboard = (result.results || []).map(button => [
          {
            text: button.title,
            callback_data: "user_button_" + button.id
          }
        ]);

        await fetch(
          `https://api.telegram.org/bot${env.BOT_TOKEN}/sendMessage`,
          {
            method: "POST",
            headers: {
              "content-type": "application/json"
            },
            body: JSON.stringify({
              chat_id: chatId,
              text: welcomeText,
              reply_markup: {
                inline_keyboard: keyboard
              }
            })
          }
        );

        return new Response("OK");
      }

      return new Response("OK");
    }

    // تنظیم Webhook
    if (url.pathname === "/set-webhook") {

      const webhookUrl =
        "https://telegram-cloudflare-worker.mojirsoleimani.workers.dev/webhook";

      const response = await fetch(
        `https://api.telegram.org/bot${env.BOT_TOKEN}/setWebhook`,
        {
          method: "POST",
          headers: {
            "content-type": "application/json"
          },
          body: JSON.stringify({
            url: webhookUrl,
            secret_token: env.WEBHOOK_SECRET
          })
        }
      );

      return new Response(await response.text(), {
        headers: {
          "content-type": "application/json; charset=UTF-8"
        }
      });
    }

    return new Response("Surgicaltechnologist Worker OK");
  }
};